// Full jugs (worksheet Week 29, two-length builders), a group inside the
// Spring-water Jugs. Two jugs of sizes a and b; each pour empties one full jug
// into a tank, and a take-back lifts one jugful out again. The tank holds
// i·a + j·b for whole i, j ≥ 0, so a level fills exactly when it is such a sum
// (the numerical semigroup generated by a and b). When a and b share no
// factor, every level after ab − a − b fills and that one does not, and a run
// of a filled levels in a row shows the gaps have stopped: one more jug of a
// repeats the run forever. When they share a factor g, only multiples of g
// fill, so the gaps never stop. Unlike the base jugs nothing is ever measured
// by pouring between jugs, which is why small levels are the hard ones.
import {esc, actionButton} from '../../expansion-controls.js';

const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const sorted = list => [...list].sort((a, b) => a - b);
const whole = value => Number.isSafeInteger(value) && value > 0;
const count = value => Number.isSafeInteger(value) && value >= 0;
const number = value => typeof value === 'string' && /^[1-9]\d*$/.test(value) ? Number(value) : value;
const ascending = list => Array.isArray(list) && list.every(whole) && list.every((v, i) => i === 0 || list[i - 1] < v);
const gcd = (a, b) => b ? gcd(b, a % b) : a;
const same = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
export const RECORD_LIMIT = 200;

// Every way to fill level n with these jugs, as counts of each jug.
export function waysFor(jugs, n) {
  if (!jugs.length) return n === 0 ? [[]] : [];
  const [a, ...rest] = jugs, out = [];
  for (let i = 0; i * a <= n; i++) for (const tail of waysFor(rest, n - i * a)) out.push([i, ...tail]);
  return out;
}
export const fills = (jugs, n) => waysFor(jugs, n).length > 0;
export const level = (jugs, counts) => jugs.reduce((total, size, k) => total + size * counts[k], 0);
// The last level that cannot be filled (null when the gaps never stop).
export function lastGap(jugs) {
  if (jugs.length < 2 || jugs.reduce(gcd) !== 1) return null;
  const m = Math.min(...jugs);
  for (let n = 1, run = 0; ; n++) {
    run = fills(jugs, n) ? run + 1 : 0;
    if (run === m) return n - m;
  }
}

const picking = q => q.mode === 'choose' || q.mode === 'design' || q.mode === 'playground';
const claims = q => q.mode === 'which' || q.mode === 'ways' || q.mode === 'last' || q.mode === 'design';
export const jugsOf = (q, b) => picking(q) ? b.pick : q.jugs;
export const targetsOf = q => q.mode === 'ways' ? [q.target] : q.targets;
export const capOf = q => Math.max(...targetsOf(q)) + Math.max(...(picking(q) ? q.choices : q.jugs));
const lit = (b, t) => b.found.some(r => r.target === t);

// Whether a claim holds on this board, or why not:
//   all: every level that fills is lit (which), or every way is found (ways)
//   last t: t cannot fill, and the m levels after it (m the smaller jug) are lit
//   never: the jugs share a factor, after every level that fills is lit
export function judge(q, b, claim) {
  const jugs = jugsOf(q, b);
  if (claim.type === 'all') {
    if (q.mode === 'ways') return b.found.length === waysFor(jugs, q.target).length ? {ok: true} : {why: 'way'};
    return q.targets.every(t => lit(b, t) || !fills(jugs, t)) ? {ok: true} : {why: 'more'};
  }
  if (claim.type === 'last') {
    const t = claim.target, m = Math.min(...jugs);
    if (fills(jugs, t)) return {why: 'filled'};
    const run = Array.from({length: m}, (_, i) => t + 1 + i);
    if (run.some(n => !fills(jugs, n))) return {why: 'later'};
    return run.every(n => lit(b, n)) ? {ok: true} : {why: 'show'};
  }
  if (claim.type === 'never') {
    if (!q.targets.every(t => lit(b, t) || !fills(jugs, t))) return {why: 'evidence'};
    return jugs.reduce(gcd) > 1 ? {ok: true} : {why: 'stops'};
  }
  return {why: 'bad'};
}
const claimShapes = q => q.mode === 'last' ? ['last', 'never'] : q.mode === 'design' ? ['last'] : claims(q) ? ['all'] : [];
function validClaim(q, b, c) {
  if (!object(c) || !claimShapes(q).includes(c.type)) return false;
  if (c.type === 'last') return q.mode === 'design' ? c.target === q.last && Object.keys(c).length === 2 : targetsOf(q).includes(c.target) && Object.keys(c).length === 2;
  return Object.keys(c).length === 1;
}
const fullKit = (q, b) => !picking(q) || b.pick.length === 2;

function validRecord(q, jugs, r) {
  return object(r) && targetsOf(q).includes(r.target) && Array.isArray(r.counts) && r.counts.length === jugs.length && r.counts.every(count) && level(jugs, r.counts) === r.target;
}
function validBoard(p, b) {
  const q = p.parameters;
  if (!object(b)) return false;
  if (picking(q)) {
    if (!ascending(b.pick) || b.pick.length > 2 || !b.pick.every(w => q.choices.includes(w))) return false;
  } else if (Object.hasOwn(b, 'pick')) return false;
  const jugs = jugsOf(q, b);
  if (!targetsOf(q).includes(b.target) || !Array.isArray(b.counts) || b.counts.length !== jugs.length || !b.counts.every(count)) return false;
  if (level(jugs, b.counts) > capOf(q)) return false;
  if (!Array.isArray(b.found) || b.found.length > RECORD_LIMIT || !b.found.every(r => validRecord(q, jugs, r))) return false;
  const unique = q.mode === 'ways' ? (r, i) => b.found.findIndex(s => same(s.counts, r.counts)) === i : (r, i) => b.found.findIndex(s => s.target === r.target) === i;
  if (!b.found.every(unique)) return false;
  if (!claims(q)) return b.done === null && b.refusal === null;
  if (b.done !== null && (!validClaim(q, b, b.done) || !fullKit(q, b) || !judge(q, b, b.done).ok)) return false;
  if (b.refusal !== null) {
    if (b.done !== null || !object(b.refusal) || !validClaim(q, b, b.refusal.claim) || !fullKit(q, b)) return false;
    if (judge(q, b, b.refusal.claim).why !== b.refusal.why || Object.keys(b.refusal).length !== 2) return false;
  }
  return true;
}
function complete(q, b) {
  if (claims(q)) return b.done !== null;
  if (q.mode === 'playground') return false;
  return fullKit(q, b) && q.targets.every(t => lit(b, t));
}
const solvedBoard = (p, b) => validBoard(p, b) && complete(p.parameters, b);

function fresh(p) {
  const q = p.parameters, pick = picking(q) ? [...(q.start || [])] : null;
  const jugs = pick || q.jugs;
  return {...(pick ? {pick} : {}), target: targetsOf(q)[0], counts: jugs.map(() => 0), found: [], done: null, refusal: null};
}
// After every move a level that matches the target is recorded: once per
// target, or once per way when the puzzle asks for every way.
function record(q, b) {
  const jugs = jugsOf(q, b);
  if (level(jugs, b.counts) !== b.target) return b;
  const r = {target: b.target, counts: [...b.counts]};
  const known = q.mode === 'ways' ? b.found.some(s => same(s.counts, r.counts)) : lit(b, r.target);
  return known ? b : {...b, found: [...b.found, r].sort((x, y) => x.target - y.target)};
}
function move(p, b, action) {
  const q = p.parameters;
  if (!validBoard(p, b) || solvedBoard(p, b) || !object(action)) return null;
  const jugs = jugsOf(q, b), next = {...b, refusal: null};
  if (action.type === 'pour' || action.type === 'back') {
    const k = jugs.indexOf(number(action.jug));
    if (k < 0) return null;
    const counts = [...b.counts];
    counts[k] += action.type === 'pour' ? 1 : -1;
    if (counts[k] < 0 || level(jugs, counts) > capOf(q)) return null;
    return record(q, {...next, counts});
  }
  if (action.type === 'empty') return b.counts.some(Boolean) ? record(q, {...next, counts: jugs.map(() => 0)}) : null;
  if (action.type === 'target') {
    const t = number(action.target);
    if (!targetsOf(q).includes(t) || t === b.target) return null;
    return record(q, {...next, target: t});
  }
  if (action.type === 'pick') {
    const w = number(action.jug);
    if (!picking(q) || !q.choices.includes(w)) return null;
    let pick;
    if (b.pick.includes(w)) pick = b.pick.filter(v => v !== w);
    else if (b.pick.length < 2) pick = sorted([...b.pick, w]);
    else return null;
    // A jug put back takes its water out of the tank, and the levels it
    // helped fill go dark; levels filled without it stay lit.
    const recount = counts => pick.map(v => b.pick.includes(v) ? counts[b.pick.indexOf(v)] : 0);
    const kept = r => b.pick.every((v, k) => pick.includes(v) || !r.counts[k]);
    return record(q, {...next, pick, counts: recount(b.counts), found: b.found.filter(kept).map(r => ({target: r.target, counts: recount(r.counts)}))});
  }
  if (['all', 'last', 'never'].includes(action.type)) {
    const claim = action.type === 'last' ? {type: 'last', target: q.mode === 'design' ? q.last : b.target} : {type: action.type};
    if (!validClaim(q, b, claim) || !fullKit(q, b)) return null;
    const verdict = judge(q, b, claim);
    return verdict.ok ? {...next, done: claim} : {...next, refusal: {claim, why: verdict.why}};
  }
  return null;
}

// Hints: jugs that can work, then the level to fill, then the way nearest the
// tank, taking jugfuls back before pouring more.
const goodPicks = new Map();
export function pickAnswers(q) {
  const key = JSON.stringify([q.mode, q.choices, q.targets, q.last]);
  if (goodPicks.has(key)) return goodPicks.get(key);
  const pairs = q.choices.flatMap((a, i) => q.choices.slice(i + 1).map(b => [a, b]));
  const good = pairs.filter(jugs => q.mode === 'design' ? lastGap(jugs) === q.last : q.targets.every(t => fills(jugs, t)));
  goodPicks.set(key, good);
  return good;
}
const plural = (n, one) => `${n} ${one}${n === 1 ? '' : 's'}`;
const jugsText = (n, size) => `${plural(n, 'jug')} of ${size}`;
function openTargets(q, b, jugs) {
  if (q.mode === 'ways') return waysFor(jugs, q.target).some(w => !b.found.some(r => same(r.counts, w))) ? [q.target] : [];
  if (q.mode === 'which') return q.targets.filter(t => !lit(b, t) && fills(jugs, t));
  if (q.mode === 'last' || q.mode === 'design') {
    const gap = lastGap(jugs);
    if (gap === null) return q.targets.filter(t => !lit(b, t) && fills(jugs, t));
    return Array.from({length: Math.min(...jugs)}, (_, i) => gap + 1 + i).filter(t => !lit(b, t));
  }
  return q.targets.filter(t => !lit(b, t));
}
function plan(q, b) {
  const jugs = jugsOf(q, b);
  if (q.mode === 'choose' || q.mode === 'design') {
    const good = pickAnswers(q), works = good.some(g => same(g, b.pick));
    if (!works) {
      const near = good.reduce((best, g) => g.filter(w => b.pick.includes(w)).length > best.filter(w => b.pick.includes(w)).length ? g : best, good[0]);
      const extra = b.pick.find(w => !near.includes(w));
      if (extra !== undefined) return {action: {type: 'pick', jug: extra}, text: `Put back the ${extra}-jug.`};
      const add = near.find(w => !b.pick.includes(w));
      return {action: {type: 'pick', jug: add}, text: `Try the ${add}-jug.`};
    }
  }
  const open = openTargets(q, b, jugs);
  if (!open.length) {
    if (q.mode === 'ways') return {action: {type: 'all'}, text: 'You have every way. Press That’s all.'};
    if (q.mode === 'which') return {action: {type: 'all'}, text: 'The other levels can’t be filled with these jugs. Press That’s all.'};
    const gap = lastGap(jugs);
    if (gap === null) return {action: {type: 'never'}, text: `Every level these jugs fill is a multiple of ${jugs.reduce(gcd)}. Press Gaps never stop.`};
    if (q.mode === 'last' && b.target !== gap) return {action: {type: 'target', target: gap}, text: `Look at level ${gap}.`};
    return {action: {type: 'last'}, text: `${gap} can’t be filled, and the ${plural(Math.min(...jugs), 'level')} after it can. Press Last gap.`};
  }
  if (!open.includes(b.target)) return {action: {type: 'target', target: open[0]}, text: `Try level ${open[0]}.`};
  const options = waysFor(jugs, b.target).filter(w => q.mode !== 'ways' || !b.found.some(r => same(r.counts, w)));
  const far = w => w.reduce((s, c, k) => s + Math.abs(c - b.counts[k]), 0);
  const goal = options.reduce((best, w) => far(w) < far(best) ? w : best, options[0]);
  const down = jugs.findIndex((_, k) => b.counts[k] > goal[k]);
  if (down >= 0) return {action: {type: 'back', jug: jugs[down]}, text: `Take one ${jugs[down]} back out.`};
  const up = jugs.findIndex((_, k) => b.counts[k] < goal[k]);
  return {action: {type: 'pour', jug: jugs[up]}, text: `Pour one more ${jugs[up]}.`};
}
function hint(p, b) {
  const q = p.parameters;
  if (!validBoard(p, b)) return {type: 'deadend', text: 'Restart to empty the tank.'};
  if (solvedBoard(p, b)) return {type: 'done'};
  if (q.mode === 'playground') return {type: 'note'};
  const next = plan(q, b);
  return {type: 'move', action: next.action, text: next.text};
}

// The tank: a tall vessel with a mark every unit, the target line, and the
// water in layers, one per jugful, shaded by jug.
function tankArt(q, jugs, counts, target) {
  const cap = capOf(q), top = 14, bottom = 316, h = bottom - top, unit = h / cap, x0 = 40, w = 92;
  const y = n => bottom - n * unit, every = cap > 30 ? 5 : cap > 14 ? 2 : 1;
  const ticks = Array.from({length: cap + 1}, (_, n) => `<line class="tank-tick${n % every ? '' : ' major'}" x1="${x0 - (n % every ? 5 : 9)}" x2="${x0}" y1="${y(n).toFixed(1)}" y2="${y(n).toFixed(1)}"/>${n % every || n === 0 ? '' : `<text class="tank-scale" x="${x0 - 12}" y="${(y(n) + 4).toFixed(1)}">${n}</text>`}`).join('');
  let at = 0;
  const layers = jugs.flatMap((size, k) => Array.from({length: counts[k]}, () => {
    const y1 = y(at + size), hh = size * unit;
    at += size;
    return `<g class="tank-layer j${k}"><rect x="${x0}" y="${y1.toFixed(1)}" width="${w}" height="${hh.toFixed(1)}"/>${hh >= 13 ? `<text x="${x0 + w / 2}" y="${(y1 + hh / 2 + 5).toFixed(1)}">${size}</text>` : ''}</g>`;
  })).join('');
  const filled = level(jugs, counts), hit = filled === target;
  const line = `<g class="tank-target${hit ? ' hit' : ''}"><line x1="${x0 - 2}" x2="${x0 + w + 8}" y1="${y(target).toFixed(1)}" y2="${y(target).toFixed(1)}"/><text x="${x0 + w + 12}" y="${(y(target) + 5).toFixed(1)}">${target}</text></g>`;
  const label = `Tank: ${filled} of target ${target}${counts.some(Boolean) ? `, from ${jugs.map((s, k) => counts[k] ? jugsText(counts[k], s) : '').filter(Boolean).join(' and ')}` : ''}. ${hit ? 'Exactly on the line.' : filled > target ? 'Over the line.' : 'Below the line.'}`;
  return `<svg class="tank-art" viewBox="0 0 180 330" role="img" aria-label="${esc(label)}">${ticks}<path class="tank-wall" d="M${x0} ${top - 6}V${bottom}H${x0 + w}V${top - 6}"/>${layers}${line}${filled ? `<text class="tank-level" x="${x0 + w / 2}" y="${(y(filled) - 5).toFixed(1)}">${filled}</text>` : ''}</svg>`;
}
const hintedClass = (shown, action) => shown && JSON.stringify(shown) === JSON.stringify(action) ? ' hinted' : '';
const jugIcon = (size, k) => `<span class="tank-jug j${k}"><svg viewBox="0 0 40 48" aria-hidden="true"><path class="tank-jug-body" d="M12 4h16v6l6 6v26a4 4 0 0 1-4 4H10a4 4 0 0 1-4-4V16l6-6z"/><path class="tank-jug-water" d="M7 20h26v22a3 3 0 0 1-3 3H10a3 3 0 0 1-3-3z"/></svg><b>${size}</b></span>`;
function jugControls(q, b, jugs, shown, solved) {
  const cap = capOf(q), now = level(jugs, b.counts);
  return `<div class="tank-jugs">${jugs.map((size, k) => {
    const pour = {type: 'pour', jug: size}, back = {type: 'back', jug: size};
    return `<div class="tank-station" role="group" aria-label="${size}-jug">${jugIcon(size, k)}${actionButton('Pour', pour, `aria-label="Pour a full ${size}-jug into the tank" ${solved || now + size > cap ? 'disabled' : ''}`).replace('class="secondary expansion-action"', `class="primary expansion-action tank-pour${hintedClass(shown, pour)}"`)}${actionButton('−', back, `aria-label="Take one ${size} back out" ${solved || !b.counts[k] ? 'disabled' : ''}`).replace('class="secondary expansion-action"', `class="secondary expansion-action tank-back${hintedClass(shown, back)}"`)}</div>`;
  }).join('')}</div>`;
}
function picker(q, b, shown, solved) {
  return `<div class="tank-picker" role="group" aria-label="Jugs to choose">${q.choices.map(w => {
    const on = b.pick.includes(w), action = {type: 'pick', jug: w};
    return actionButton(String(w), action, `aria-label="${w}-jug" aria-pressed="${on}" ${(b.pick.length >= 2 && !on) || solved ? 'disabled' : ''}`).replace('class="secondary expansion-action"', `class="secondary expansion-action tank-pick${hintedClass(shown, action)}"`);
  }).join('')}</div>`;
}
function targetRow(q, b, jugs, shown, solved) {
  const done = b.done, crossed = t => done && done.type !== 'last' && !lit(b, t) && q.mode !== 'ways' || (done?.type === 'last' && t === done.target);
  return `<div class="tank-targets${q.targets.length > 16 ? ' many' : ''}" role="group" aria-label="Levels">${q.targets.map(t => {
    const action = {type: 'target', target: t}, state = lit(b, t) ? ', filled' : crossed(t) ? ', cannot be filled' : '';
    return actionButton(String(t), action, `aria-label="Level ${t}${state}" aria-pressed="${b.target === t}" ${solved ? 'disabled' : ''}`).replace('class="secondary expansion-action"', `class="secondary expansion-action tank-target${lit(b, t) ? ' found' : ''}${crossed(t) ? ' crossed' : ''}${hintedClass(shown, action)}"`);
  }).join('')}${q.mode === 'last' ? '<span class="tank-more" aria-hidden="true">…</span>' : ''}</div>`;
}
const wayHTML = (jugs, counts) => `<li class="tank-way" aria-label="${esc(jugs.map((s, k) => counts[k] ? jugsText(counts[k], s) : '').filter(Boolean).join(' and '))}">${jugs.flatMap((s, k) => Array.from({length: counts[k]}, () => `<i class="j${k}" style="--n:${s}">${s}</i>`)).join('')}</li>`;
const REFUSALS = {
  more: () => 'Another level can be filled.',
  way: () => 'There is another way.',
  filled: t => `Level ${t} can be filled.`,
  later: t => `A level after ${t} can’t be filled either.`,
  show: t => `Show that every level after ${t} can be filled.`,
  evidence: () => 'Fill every level you can first.',
  stops: () => 'The gaps do stop.'
};
function render(p, attempt) {
  const q = p.parameters, b = attempt.board, jugs = jugsOf(q, b), solved = solvedBoard(p, b);
  const shown = attempt.hintLevel >= 2 && !solved && q.mode !== 'playground' ? plan(q, b).action : null;
  const tools = [actionButton('Empty', {type: 'empty'}, b.counts.some(Boolean) && !solved ? '' : 'disabled')];
  const claimButton = (label, action, enabled = true) => actionButton(label, action, enabled ? '' : 'disabled').replace('class="secondary expansion-action"', `class="primary expansion-action tank-claim${hintedClass(shown, action)}"`);
  if (!solved && (q.mode === 'which' || q.mode === 'ways')) tools.push(claimButton('That’s all', {type: 'all'}));
  if (!solved && q.mode === 'last') tools.push(claimButton(`Last gap is ${b.target}`, {type: 'last'}), claimButton('Gaps never stop', {type: 'never'}));
  if (!solved && q.mode === 'design') tools.push(claimButton(`Last gap is ${q.last}`, {type: 'last'}, b.pick.length === 2));
  const ways = q.mode === 'ways' && b.found.length ? `<ol class="tank-ways" aria-label="Ways found">${b.found.map(r => wayHTML(jugs, r.counts)).join('')}</ol>` : '';
  const note = b.refusal ? REFUSALS[b.refusal.why](b.refusal.claim.target) : '';
  const status = `Level ${level(jugs, b.counts)}, target ${b.target}.`;
  return `<div class="measurement-board tank-puzzle mode-${q.mode}">${picking(q) ? picker(q, b, shown, solved) : ''}${targetsOf(q).length > 1 ? targetRow(q, b, jugs, shown, solved) : ''}<div class="tank-main">${tankArt(q, jugs, b.counts, b.target)}${jugs.length ? jugControls(q, b, jugs, shown, solved) : ''}</div><div class="tank-tools">${tools.join('')}</div>${ways}${note ? `<p class="tank-note" role="status">${esc(note)}</p>` : `<p class="sr-only" role="status">${esc(status)}</p>`}</div>`;
}

export const tankMechanics = {
  tank: {
    fresh,
    valid: validBoard,
    solved: solvedBoard,
    move,
    hint,
    render,
    demo: 'Pour empties a full jug into the tank; − takes one jugful back out. Fill the tank exactly to the line.'
  }
};

// The family seam entry (dist/families.js). The puzzles join the Spring-water
// Jugs as its Full jugs group, so the module adds no satchel family.
export default {
  id: 'tank',
  mechanics: tankMechanics,
  pack: new URL('./tank.json', import.meta.url).href,
  css: new URL('./tank.css', import.meta.url).href,
  focus: '.tank-pour:not(:disabled),.tank-target:not(:disabled)'
};
